<template>
  <div class="page">
    <div class="head"><div><h2>计量器具管理</h2><p>台账、校准、使用、借还、维修和报废全生命周期管理</p></div><el-space><el-upload :show-file-list="false" :auto-upload="false" accept=".xlsx,.xls" :on-change="handleImport"><el-button>Excel导入</el-button></el-upload><el-button @click="handleExport">Excel导出</el-button><el-button @click="openTrace">批次追溯</el-button><el-button @click="openAgencies">外校机构</el-button><el-button @click="openReminders">到期提醒</el-button><el-button @click="openScraps">报废审批</el-button><el-button type="primary" @click="openCreate">新增器具</el-button></el-space></div>
    <el-row :gutter="12" class="summary"><el-col :span="6"><el-card><span>器具总数</span><b>{{stats.total||0}}</b></el-card></el-col><el-col :span="6"><el-card><span>维修次数</span><b>{{stats.maintenanceCount||0}}</b></el-card></el-col><el-col :span="6"><el-card><span>维修费用</span><b>{{stats.maintenanceCost||0}}</b></el-card></el-col><el-col :span="6"><el-card><span>已报废</span><b>{{stats.scrapCount||0}}</b></el-card></el-col></el-row>
    <el-card class="status-card"><div ref="statusChartEl" class="status-chart"/></el-card>
    <el-card>
      <div class="bar"><el-input v-model="query.keyword" placeholder="器具编号或名称" clearable @keyup.enter="load"/><el-select v-model="query.status" clearable placeholder="全部状态"><el-option v-for="s in states" :key="s" :label="s" :value="s"/></el-select><el-button @click="load">查询</el-button></div>
      <el-table :data="rows" v-loading="loading"><el-table-column prop="instrumentCode" label="器具编号"/><el-table-column prop="instrumentName" label="名称"/><el-table-column prop="model" label="型号"/><el-table-column prop="accuracyGrade" label="精度等级"/><el-table-column prop="nextCalibrationDate" label="下次校准"/><el-table-column prop="status" label="状态"><template #default="{row}"><el-tag>{{row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="390"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link @click="openHistory(row)">履历</el-button><el-button link @click="printLabel(row)">二维码</el-button><el-button link type="warning" @click="openAction('校准',row)">校准</el-button><el-dropdown @command="(cmd:string)=>openAction(cmd,row)"><el-button link>更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="使用">登记使用</el-dropdown-item><el-dropdown-item v-if="row.status==='借出'" command="归还">归还</el-dropdown-item><el-dropdown-item v-else command="借出">借出</el-dropdown-item><el-dropdown-item command="维修">故障报修</el-dropdown-item><el-dropdown-item command="报废">报废申请</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column></el-table>
      <el-pagination v-model:current-page="query.page" :page-size="query.size" :total="total" layout="total,prev,pager,next" @current-change="load"/>
    </el-card>
    <el-dialog v-model="assetVisible" :title="asset.id?'编辑器具':'新增器具'" width="640px"><el-form :model="asset" label-width="100px"><el-row :gutter="16"><el-col :span="12"><el-form-item label="器具编号" required><el-input v-model="asset.instrumentCode"/></el-form-item></el-col><el-col :span="12"><el-form-item label="器具名称" required><el-input v-model="asset.instrumentName"/></el-form-item></el-col><el-col :span="12"><el-form-item label="型号"><el-input v-model="asset.model"/></el-form-item></el-col><el-col :span="12"><el-form-item label="精度等级"><el-input v-model="asset.accuracyGrade"/></el-form-item></el-col><el-col :span="12"><el-form-item label="责任人"><el-input v-model="asset.keeperName"/></el-form-item></el-col><el-col :span="12"><el-form-item label="校准周期(月)"><el-input-number v-model="asset.calibrationCycleMonths" :min="1"/></el-form-item></el-col></el-row><el-form-item label="存放位置"><el-input v-model="asset.storageLocation"/></el-form-item><el-form-item label="备注"><el-input v-model="asset.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="assetVisible=false">取消</el-button><el-button type="primary" @click="saveAsset">保存</el-button></template></el-dialog>
    <el-dialog v-model="actionVisible" :title="actionType" width="560px"><el-form :model="action" label-width="105px"><template v-if="actionType==='校准'"><el-form-item label="校准日期"><el-date-picker v-model="action.calibrationDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="结论"><el-select v-model="action.result"><el-option label="合格" value="合格"/><el-option label="不合格" value="不合格"/><el-option label="限用" value="限用"/></el-select></el-form-item><el-form-item label="有效期至"><el-date-picker v-model="action.validUntil" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="证书编号"><el-input v-model="action.certificateNo"/></el-form-item></template><template v-else-if="actionType==='使用'"><el-form-item label="工单号"><el-input v-model="action.workOrderNo"/></el-form-item><el-form-item label="产品批次"><el-input v-model="action.productBatchNo"/></el-form-item><el-form-item label="测量项"><el-input v-model="action.measurementItem"/></el-form-item><el-form-item label="测量值"><el-input v-model="action.measuredValue"/></el-form-item></template><template v-else-if="actionType==='借出'"><el-form-item label="借用人"><el-input v-model="action.borrowerName"/></el-form-item><el-form-item label="预计归还"><el-date-picker v-model="action.expectedReturnDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="用途"><el-input v-model="action.purpose" type="textarea"/></el-form-item></template><template v-else-if="actionType==='归还'"><el-form-item label="外观检查"><el-select v-model="action.appearance"><el-option label="正常" value="正常"/><el-option label="损坏" value="损坏"/><el-option label="缺失" value="缺失"/></el-select></el-form-item></template><template v-else-if="actionType==='维修'"><el-form-item label="故障现象"><el-input v-model="action.faultDescription" type="textarea"/></el-form-item><el-form-item label="发现人"><el-input v-model="action.finderName"/></el-form-item></template><template v-else><el-form-item label="报废原因"><el-input v-model="action.scrapReason" type="textarea"/></el-form-item><el-form-item label="处置方式"><el-select v-model="action.disposalMethod"><el-option label="销毁" value="销毁"/><el-option label="退回供应商" value="退回供应商"/><el-option label="其他" value="其他"/></el-select></el-form-item></template></el-form><template #footer><el-button @click="actionVisible=false">取消</el-button><el-button type="primary" @click="submitAction">提交</el-button></template></el-dialog>
    <el-drawer v-model="historyVisible" :title="`${current?.instrumentName||''} 全生命周期履历`" size="720px"><el-tabs><el-tab-pane v-for="tab in historyTabs" :key="tab.key" :label="`${tab.label}（${history[tab.key]?.length||0}）`"><el-table :data="history[tab.key]||[]" size="small"><el-table-column v-for="col in tab.cols" :key="col.prop" :prop="col.prop" :label="col.label" show-overflow-tooltip/><el-table-column v-if="tab.key==='maintenance'" label="操作" width="100"><template #default="{row}"><el-button v-if="row.status==='维修中'" link type="primary" @click="openRepairComplete(row)">完成维修</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></el-drawer>
    <el-dialog v-model="reminderVisible" title="计量计划与到期提醒" width="820px"><el-alert title="每日自动生成校准任务并通过站内消息推送；同时展示借用逾期" type="warning" :closable="false"/><h4>校准任务（{{reminders.calibrationTasks?.length||0}}）</h4><el-table :data="reminders.calibrationTasks||[]" size="small"><el-table-column prop="instrumentId" label="器具ID"/><el-table-column prop="planDate" label="计划日期"/><el-table-column prop="agency" label="校准机构"/><el-table-column prop="responsibleName" label="责任人"/><el-table-column prop="status" label="状态"/></el-table><h4>未来30天到期（{{reminders.calibrationDue?.length||0}}）</h4><el-table :data="reminders.calibrationDue||[]" size="small"><el-table-column prop="instrumentCode" label="编号"/><el-table-column prop="instrumentName" label="名称"/><el-table-column prop="keeperName" label="责任人"/><el-table-column prop="nextCalibrationDate" label="到期日期"/></el-table><h4>借用逾期（{{reminders.lendingOverdue?.length||0}}）</h4><el-table :data="reminders.lendingOverdue||[]" size="small"><el-table-column prop="instrumentId" label="器具ID"/><el-table-column prop="borrowerName" label="借用人"/><el-table-column prop="expectedReturnDate" label="预计归还"/><el-table-column prop="purpose" label="用途"/></el-table></el-dialog>
    <el-dialog v-model="scrapVisible" title="计量器具报废审批" width="900px"><el-table :data="scrapRows"><el-table-column prop="instrumentId" label="器具ID" width="90"/><el-table-column prop="scrapReason" label="报废原因"/><el-table-column prop="applicantName" label="申请人"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="210"><template #default="{row}"><el-button v-if="!row.metrologyApprover" link type="primary" @click="approve(row,'METROLOGY')">计量审批</el-button><el-button v-if="row.metrologyApprover&&!row.qualityApprover" link type="success" @click="approve(row,'QUALITY')">质量审批</el-button><span v-if="row.qualityApprover">审批完成</span></template></el-table-column></el-table></el-dialog>
    <el-dialog v-model="repairCompleteVisible" title="完成维修并转重新校准" width="520px"><el-form :model="repairForm" label-width="90px"><el-form-item label="维修单位"><el-input v-model="repairForm.repairVendor"/></el-form-item><el-form-item label="维修日期" required><el-date-picker v-model="repairForm.repairDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="维修内容" required><el-input v-model="repairForm.repairContent" type="textarea"/></el-form-item><el-form-item label="维修费用"><el-input-number v-model="repairForm.repairCost" :min="0"/></el-form-item></el-form><template #footer><el-button @click="repairCompleteVisible=false">取消</el-button><el-button type="primary" @click="submitRepairComplete">提交</el-button></template></el-dialog>
    <el-dialog v-model="traceVisible" title="产品批次—计量器具双向追溯" width="900px"><div class="bar"><el-input v-model="traceQuery.productBatchNo" placeholder="产品批次号"/><el-input v-model="traceQuery.operatorName" placeholder="操作人"/><el-button type="primary" @click="loadTrace">查询</el-button></div><el-table :data="traceRows"><el-table-column prop="productBatchNo" label="产品批次"/><el-table-column prop="workOrderNo" label="工单号"/><el-table-column prop="instrumentId" label="器具ID"/><el-table-column prop="processName" label="工序"/><el-table-column prop="measurementItem" label="测量项"/><el-table-column prop="measuredValue" label="测量值"/><el-table-column prop="operatorName" label="操作人"/><el-table-column prop="usedAt" label="使用时间"/></el-table></el-dialog>
    <el-dialog v-model="agencyVisible" title="外部校准机构管理" width="900px"><el-button type="primary" @click="editAgency()">新增机构</el-button><el-table :data="agencyRows"><el-table-column prop="agencyName" label="机构名称"/><el-table-column prop="certificateNo" label="资质证书"/><el-table-column prop="contactName" label="联系人"/><el-table-column prop="contactPhone" label="联系电话"/><el-table-column prop="qualificationExpiryDate" label="资质有效期"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="editAgency(row)">编辑</el-button></template></el-table-column></el-table></el-dialog>
    <el-dialog v-model="agencyEditorVisible" :title="agencyForm.id?'编辑外校机构':'新增外校机构'" width="520px"><el-form :model="agencyForm" label-width="100px"><el-form-item label="机构名称" required><el-input v-model="agencyForm.agencyName"/></el-form-item><el-form-item label="资质证书"><el-input v-model="agencyForm.certificateNo"/></el-form-item><el-form-item label="联系人"><el-input v-model="agencyForm.contactName"/></el-form-item><el-form-item label="联系电话"><el-input v-model="agencyForm.contactPhone"/></el-form-item><el-form-item label="资质有效期"><el-date-picker v-model="agencyForm.qualificationExpiryDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="状态"><el-select v-model="agencyForm.status"><el-option label="有效" value="有效"/><el-option label="停用" value="停用"/></el-select></el-form-item></el-form><template #footer><el-button @click="agencyEditorVisible=false">取消</el-button><el-button type="primary" @click="saveAgency">保存</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import {nextTick,onBeforeUnmount,onMounted,reactive,ref} from 'vue'; import {ElMessage} from 'element-plus'; import QRCode from 'qrcode';import*as echarts from'echarts'; import {addCalibration,addUsage,approveScrap,completeRepair,createCalibrationAgency,createInstrument,exportInstruments,getCalibrationAgencies,getInstrumentHistory,getInstruments,getMeasurementReminders,getMeasurementStats,getScrapApplications,getUsageTrace,importInstruments,lendInstrument,repairInstrument,returnInstrumentByInstrument,scrapInstrument,updateCalibrationAgency,updateInstrument,type Instrument} from '@/api/measurement'
const states=['合格可用','待校准','超期','借出','维修中','不合格','已报废']; const query=reactive({page:1,size:20,keyword:'',status:''}); const rows=ref<Instrument[]>([]),total=ref(0),loading=ref(false),assetVisible=ref(false),actionVisible=ref(false),historyVisible=ref(false),reminderVisible=ref(false),scrapVisible=ref(false),repairCompleteVisible=ref(false),traceVisible=ref(false),agencyVisible=ref(false),agencyEditorVisible=ref(false),selectedId=ref<number>(),selectedRepairId=ref<number>(),actionType=ref(''),current=ref<Instrument>(),statusChartEl=ref<HTMLElement>();let statusChart:echarts.ECharts|undefined; const history=reactive<Record<string,any[]>>({}),reminders=reactive<Record<string,any[]>>({}),stats=reactive<Record<string,any>>({}),scrapRows=ref<any[]>([]),traceRows=ref<any[]>([]),agencyRows=ref<any[]>([]);const traceQuery=reactive({productBatchNo:'',operatorName:''}),repairForm=reactive<Record<string,any>>({}),agencyForm=reactive<Record<string,any>>({}); const historyTabs=[{key:'calibrations',label:'校准',cols:[{prop:'calibrationDate',label:'校准日期'},{prop:'result',label:'结论'},{prop:'certificateNo',label:'证书编号'},{prop:'validUntil',label:'有效期至'}]},{key:'usages',label:'使用',cols:[{prop:'usedAt',label:'使用时间'},{prop:'workOrderNo',label:'工单号'},{prop:'productBatchNo',label:'产品批次'},{prop:'measurementItem',label:'测量项'}]},{key:'lendings',label:'借还',cols:[{prop:'borrowerName',label:'借用人'},{prop:'expectedReturnDate',label:'预计归还'},{prop:'returnedAt',label:'归还时间'},{prop:'appearanceResult',label:'外观检查'}]},{key:'maintenance',label:'维修',cols:[{prop:'foundAt',label:'发现时间'},{prop:'faultDescription',label:'故障现象'},{prop:'repairContent',label:'维修内容'},{prop:'status',label:'状态'}]},{key:'scraps',label:'报废',cols:[{prop:'createdAt',label:'申请时间'},{prop:'scrapReason',label:'原因'},{prop:'status',label:'状态'},{prop:'qualityApprover',label:'质量审批人'}]}]; const empty=():Instrument=>({instrumentCode:'',instrumentName:'',calibrationCycleMonths:12}); const asset=reactive<Instrument>(empty()); const action=reactive<Record<string,any>>({})
async function load(){loading.value=true;try{const [r,s]=await Promise.all([getInstruments(query),getMeasurementStats()]);rows.value=r.data?.list||[];total.value=r.data?.total||0;Object.assign(stats,s.data||{});await nextTick();renderStatusChart()}finally{loading.value=false}}function renderStatusChart(){const data=Object.entries(stats.byStatus||{}).map(([name,value])=>({name,value}));statusChart=statusChart||echarts.init(statusChartEl.value!);statusChart.setOption({title:{text:'计量器具状态分布',textStyle:{fontSize:15}},tooltip:{trigger:'item'},legend:{orient:'vertical',right:20,top:'center'},series:[{type:'pie',radius:['40%','70%'],center:['42%','55%'],data}]})} function openCreate(){Object.assign(asset,empty());assetVisible.value=true} function edit(row:Instrument){Object.assign(asset,row);assetVisible.value=true} async function saveAsset(){if(!asset.instrumentCode||!asset.instrumentName)return ElMessage.warning('请填写器具编号和名称');asset.id?await updateInstrument(asset.id,asset):await createInstrument(asset);assetVisible.value=false;ElMessage.success('保存成功');load()} function openAction(type:string,row:Instrument){selectedId.value=row.id;actionType.value=type;Object.keys(action).forEach(k=>delete action[k]);Object.assign(action,{result:'合格',appearance:'正常'});actionVisible.value=true}
async function submitAction(){if(!selectedId.value)return;const id=selectedId.value;if(actionType.value==='校准')await addCalibration(id,action as any);else if(actionType.value==='使用')await addUsage(id,action);else if(actionType.value==='借出')await lendInstrument(id,action);else if(actionType.value==='归还')await returnInstrumentByInstrument(id,action.appearance);else if(actionType.value==='维修')await repairInstrument(id,action);else await scrapInstrument(id,action);actionVisible.value=false;ElMessage.success(`${actionType.value}已提交`);load()}
async function openHistory(row:Instrument){if(!row.id)return;current.value=row;Object.assign(history,(await getInstrumentHistory(row.id)).data||{});historyVisible.value=true} async function openReminders(){Object.assign(reminders,(await getMeasurementReminders()).data||{});reminderVisible.value=true} async function openScraps(){scrapRows.value=(await getScrapApplications()).data||[];scrapVisible.value=true} async function approve(row:any,stage:'METROLOGY'|'QUALITY'){await approveScrap(row.id,stage);ElMessage.success('审批已完成');await openScraps();load()} async function printLabel(row:Instrument){const code=row.qrCode||`QMS-MT-${row.instrumentCode}`;const url=await QRCode.toDataURL(code,{width:180,margin:1});const win=window.open('','_blank','width=520,height=620');if(!win)return ElMessage.warning('浏览器阻止了打印窗口');win.document.write(`<html><head><title>计量器具标签</title><style>body{text-align:center;font-family:sans-serif;padding:40px}img{width:180px;height:180px}h2{margin-bottom:8px}</style></head><body><h2>${row.instrumentName}</h2><div>${row.instrumentCode}</div><p><img src="${url}" onload="window.print()"/></p><div>${code}</div></body></html>`);win.document.close()}
function openRepairComplete(row:any){selectedRepairId.value=row.id;Object.keys(repairForm).forEach(k=>delete repairForm[k]);repairCompleteVisible.value=true}async function submitRepairComplete(){if(!selectedRepairId.value)return;await completeRepair(selectedRepairId.value,repairForm);repairCompleteVisible.value=false;ElMessage.success('维修完成，器具已转待校准');if(current.value)await openHistory(current.value);load()}async function openTrace(){traceVisible.value=true;await loadTrace()}async function loadTrace(){traceRows.value=(await getUsageTrace(traceQuery)).data||[]}async function openAgencies(){agencyRows.value=(await getCalibrationAgencies()).data||[];agencyVisible.value=true}function editAgency(row?:any){Object.keys(agencyForm).forEach(k=>delete agencyForm[k]);Object.assign(agencyForm,row||{status:'有效'});agencyEditorVisible.value=true}async function saveAgency(){if(!agencyForm.agencyName)return ElMessage.warning('请填写机构名称');agencyForm.id?await updateCalibrationAgency(agencyForm.id,agencyForm):await createCalibrationAgency(agencyForm);agencyEditorVisible.value=false;ElMessage.success('保存成功');await openAgencies()}
async function handleImport(upload:any){if(!upload.raw)return;const r=await importInstruments(upload.raw);ElMessage.success(`导入完成：新增 ${r.data?.created||0}，更新 ${r.data?.updated||0}`);load()}async function handleExport(){const response=await exportInstruments();const blob=response.data instanceof Blob?response.data:new Blob([response.data]);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='计量器具台账.xlsx';a.click();URL.revokeObjectURL(a.href)}
onBeforeUnmount(()=>statusChart?.dispose());onMounted(load)
</script>
<style scoped>.page{padding:20px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.head h2{margin:0;color:#1b3a5b}.head p{color:#8c9ba8;margin:6px 0 0}.summary,.status-card{margin-bottom:14px}.summary span{font-size:12px;color:#8c9ba8}.summary b{display:block;font-size:24px;color:#1b3a5b;margin-top:7px}.status-chart{height:230px}.bar{display:flex;gap:12px;margin-bottom:16px}.bar .el-input{width:250px}.bar .el-select{width:130px}.el-pagination{justify-content:flex-end;margin-top:16px}</style>
